def style_workbook(wb) -> None:
    header_fill = PatternFill("solid", fgColor="4472C4")
    header_font = Font(bold=True, color="FFFFFF")
    benchmark_fill = PatternFill("solid", fgColor="FFF2CC")
    widths = {
        "کد": 24, "نام": 34, "تعریف": 55, "شرح": 55, "توضیحات": 50,
        "منبع": 54, "یادداشت": 55, "آدرس": 48, "سامانه": 36,
        "فرآیند": 42, "ورودی": 38, "خروجی": 38, "قوانین": 40,
    }
    for ws in wb.worksheets:
        ws.sheet_view.rightToLeft = True
        if ws.max_row >= 1:
            for cell in ws[1]:
                if cell.value not in (None, ""):
                    cell.fill = header_fill
                    cell.font = header_font
                    cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            ws.row_dimensions[1].height = 32
        if ws.title not in {"راهنما", "راهنمای ستون‌ها", "فهرست‌های مجاز"}:
            ws.freeze_panes = "A2"
            ws.auto_filter.ref = f"A1:{get_column_letter(ws.max_column)}{ws.max_row}"
        for row in ws.iter_rows(min_row=2):
            row_source = " | ".join(str(c.value or "") for c in row)
            is_benchmark = ("tums.ac.ir" in row_source or "iums.ac.ir" in row_source) and "sbmu.ac.ir" not in row_source
            for cell in row:
                cell.alignment = Alignment(vertical="top", wrap_text=True)
                if is_benchmark:
                    cell.fill = benchmark_fill
        for col in range(1, ws.max_column + 1):
            header = str(ws.cell(1, col).value or "")
            width = 18
            for token, candidate in widths.items():
                if token in header:
                    width = max(width, candidate)
            ws.column_dimensions[get_column_letter(col)].width = min(width, 60)


def validate(wb) -> list[str]:
    errors: list[str] = []
    code_sheets = ["واحدهای سازمانی", "افراد", "نقش‌ها", "سامانه‌ها", "قابلیت‌ها", "واژه‌ها", "عناصر داده", "فرآیندها", "فعالیت‌ها"]
    for sheet in code_sheets:
        values = [str(r[0]).strip() for r in wb[sheet].iter_rows(min_row=2, values_only=True) if r[0] not in (None, "")]
        duplicates = sorted({v for v in values if values.count(v) > 1})
        if duplicates:
            errors.append(f"کد تکراری در {sheet}: {duplicates}")

    units = {r[1] for r in wb["واحدهای سازمانی"].iter_rows(min_row=2, values_only=True) if r[1]}
    systems = {r[1] for r in wb["سامانه‌ها"].iter_rows(min_row=2, values_only=True) if r[1]}
    processes = {r[1] for r in wb["فرآیندها"].iter_rows(min_row=2, values_only=True) if r[1]}
    roles = {r[1] for r in wb["نقش‌ها"].iter_rows(min_row=2, values_only=True) if r[1]}

    def split_values(value) -> list[str]:
        return [part.strip() for part in str(value or "").split(",") if part.strip()]

    for r in wb["فرآیندها"].iter_rows(min_row=2, values_only=True):
        if not r[0]:
            continue
        if r[3] not in units:
            errors.append(f"واحد مسئول ناشناخته در {r[0]}: {r[3]}")
        for item in split_values(r[13]):
            if item not in systems:
                errors.append(f"سامانه ناشناخته در {r[0]}: {item}")

    for r in wb["فعالیت‌ها"].iter_rows(min_row=2, values_only=True):
        if not r[0]:
            continue
        if r[2] not in processes:
            errors.append(f"فرآیند ناشناخته در {r[0]}: {r[2]}")
        if r[4] and r[4] not in roles:
            errors.append(f"نقش ناشناخته در {r[0]}: {r[4]}")
        for item in split_values(r[5]):
            if item not in systems:
                errors.append(f"سامانه ناشناخته در {r[0]}: {item}")

    for r in wb["قابلیت‌ها"].iter_rows(min_row=2, values_only=True):
        if not r[0]:
            continue
        if r[2] not in systems:
            errors.append(f"سامانه ناشناخته در {r[0]}: {r[2]}")
        for item in split_values(r[5]):
            if item not in processes:
                errors.append(f"فرآیند ناشناخته در {r[0]}: {item}")

    for r in wb["عناصر داده"].iter_rows(min_row=2, values_only=True):
        if not r[0]:
            continue
        if r[7] and r[7] not in units:
            errors.append(f"واحد مسئول داده ناشناخته در {r[0]}: {r[7]}")
        for item in split_values(r[8]):
            if item not in systems:
                errors.append(f"سامانه مرجع ناشناخته در {r[0]}: {item}")

    allowed_system_status = {"فعال", "در حال توسعه", "در حال جایگزینی", "غیرفعال"}
    allowed_capability_status = {"فعال", "ناقص", "در حال توسعه", "غیرفعال"}
    allowed_levels = {"کلان", "اصلی", "زیرفرآیند"}
    allowed_types = {"متن", "عدد", "تاریخ", "زمان", "بولی", "فهرست انتخابی", "شناسه", "پرونده", "پیوند"}
    allowed_sensitivity = {"عمومی", "داخلی", "محرمانه", ""}
    for r in wb["سامانه‌ها"].iter_rows(min_row=2, values_only=True):
        if r[0] and r[3] not in allowed_system_status:
            errors.append(f"وضعیت سامانه نامعتبر در {r[0]}: {r[3]}")
    for r in wb["قابلیت‌ها"].iter_rows(min_row=2, values_only=True):
        if r[0] and r[3] not in allowed_capability_status:
            errors.append(f"وضعیت قابلیت نامعتبر در {r[0]}: {r[3]}")
    for r in wb["فرآیندها"].iter_rows(min_row=2, values_only=True):
        if r[0] and r[2] not in allowed_levels:
            errors.append(f"سطح فرآیند نامعتبر در {r[0]}: {r[2]}")
    for r in wb["عناصر داده"].iter_rows(min_row=2, values_only=True):
        if r[0] and r[3] not in allowed_types:
            errors.append(f"نوع داده نامعتبر در {r[0]}: {r[3]}")
        if r[0] and (r[9] or "") not in allowed_sensitivity:
            errors.append(f"حساسیت نامعتبر در {r[0]}: {r[9]}")
    return errors


def finalize(template: Path = TEMPLATE) -> None:
    wb = openpyxl.load_workbook(template)

    # نقش‌ها
    upsert_rows(wb["نقش‌ها"], ADDITIONAL_ROLES)

    # سامانه‌های موجود: رفع تعارض گلستان/هم‌آوا و تکمیل رکوردهای جاری.
